"""Policy compilation and canonical image export.

The compiler builds a small deterministic model directly from the parsed
predicate AST, then minimises it and exports the protocol's canonical
residual numbering.  It uses only bounded integer/array operations, so a
large policy does not require subprocesses or unbounded automata libraries.
"""
from __future__ import annotations

from array import array
from collections import deque
from syntax import (ATOM_KINDS, NONMATCH_KINDS, PolicyError, parse_policy)

DENY = 4294967295
MAX_ROWS = 8192

# ---------------------------------------------------------------------------
# Small complete DFAs for the four atom languages.
# State 0 is the initial state in every component.

def _startswith_dfa(p, m):
    k = len(p)
    if k == 0:
        return 1, [[0] * m], [True]
    n = k + 2                 # 0..k-1 progress, k accepting, k+1 dead
    dead = k + 1
    rows = []
    for i in range(k):
        want = p[i]
        rows.append([i + 1 if a == want else dead for a in range(m)])
    rows.append([k] * m)
    rows.append([dead] * m)
    acc = [False] * n
    acc[k] = True
    return n, rows, acc

def _prefix_function(p):
    pi = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j and p[i] != p[j]:
            j = pi[j - 1]
        if p[i] == p[j]:
            j += 1
        pi[i] = j
    return pi

def _endswith_dfa(p, m):
    k = len(p)
    if k == 0:
        return 1, [[0] * m], [True]
    pi = _prefix_function(p)
    n = k + 1                 # KMP prefix lengths 0..k; k accepts
    rows = []
    for i in range(n):
        row = []
        for c in range(m):
            j = pi[i - 1] if i == k else i
            while j and p[j] != c:
                j = pi[j - 1]
            if j < k and p[j] == c:
                j += 1
            row.append(j)
        rows.append(row)
    acc = [i == k for i in range(n)]
    return n, rows, acc

def _contains_dfa(p, m):
    k = len(p)
    if k == 0:
        return 1, [[0] * m], [True]
    pi = _prefix_function(p)
    n = k + 1                 # 0..k-1 not-yet-seen progress, k seen
    rows = []
    for i in range(k):
        row = []
        for c in range(m):
            j = i
            while j and p[j] != c:
                j = pi[j - 1]
            if p[j] == c:
                j += 1
            if j == k:
                j = k
            row.append(j)
        rows.append(row)
    rows.append([k] * m)
    acc = [i == k for i in range(n)]
    return n, rows, acc

def _nonmatch_component(kind, p, m):
    if kind == "startswith":
        return _startswith_dfa(p, m)
    if kind == "endswith":
        return _endswith_dfa(p, m)
    if kind == "contains":
        return _contains_dfa(p, m)
    raise PolicyError("atom kind")

# ---------------------------------------------------------------------------
# DFA minimisation (Hopcroft, complete automata, including a shared dead
# sink supplied by the caller).  Returns block_of[state].

def _hopcroft(n, m, trans, accept):
    if n <= 1:
        return [0] * n
    accepting = [i for i in range(n) if accept[i]]
    nonaccepting = [i for i in range(n) if not accept[i]]
    if not accepting or not nonaccepting:
        return [0] * n
    blocks = [accepting, nonaccepting]
    block_of = [0] * n
    for q in nonaccepting:
        block_of[q] = 1

    # For each symbol, CSR inverse transitions.
    offsets = []
    sources = []
    for c in range(m):
        counts = [0] * n
        for q in range(n):
            counts[trans[q][c]] += 1
        off = array('I', [0]) * (n + 1)
        s = 0
        for t in range(n):
            off[t] = s
            s += counts[t]
        off[n] = s
        pos = list(off[:n])
        src = array('I', [0]) * n
        for q in range(n):
            t = trans[q][c]
            src[pos[t]] = q
            pos[t] += 1
        offsets.append(off)
        sources.append(src)

    # Worklist of (block, symbol), stored encoded as block*m+symbol.
    W = deque()
    inW = set()
    small = 0 if len(blocks[0]) <= len(blocks[1]) else 1
    for c in range(m):
        e = small * m + c
        inW.add(e)
        W.append(e)

    mark = [0] * n
    stamp = 0
    while W:
        e = W.popleft()
        if e not in inW:
            continue
        inW.remove(e)
        aid, c = divmod(e, m)
        A = blocks[aid]
        off = offsets[c]
        src = sources[c]
        stamp += 1
        xs = []
        for t in A:
            for z in range(off[t], off[t + 1]):
                q = src[z]
                if mark[q] != stamp:
                    mark[q] = stamp
                    xs.append(q)
        if not xs:
            continue
        touched = {}
        for q in xs:
            b = block_of[q]
            try:
                touched[b].append(q)
            except KeyError:
                touched[b] = [q]
        for b, xb in touched.items():
            Y = blocks[b]
            if len(xb) == len(Y):
                continue
            # Xb are exactly the marked members of Y.  Keep them in block b
            # and move the unmarked rest to a fresh block.
            rest = [q for q in Y if mark[q] != stamp]
            newid = len(blocks)
            blocks[b] = xb
            blocks.append(rest)
            for q in rest:
                block_of[q] = newid
            xlen = len(xb)
            rlen = len(rest)
            smaller = b if xlen <= rlen else newid
            had = False
            for c2 in range(m):
                if (b * m + c2) in inW:
                    had = True
                    break
            if had:
                for c2 in range(m):
                    olde = b * m + c2
                    if olde in inW:
                        inW.remove(olde)
                        e1 = b * m + c2
                        e2 = newid * m + c2
                        if e1 not in inW:
                            inW.add(e1); W.append(e1)
                        if e2 not in inW:
                            inW.add(e2); W.append(e2)
                    else:
                        se = smaller * m + c2
                        if se not in inW:
                            inW.add(se); W.append(se)
            else:
                for c2 in range(m):
                    se = smaller * m + c2
                    if se not in inW:
                        inW.add(se); W.append(se)
    return block_of

# Moore partition refinement is used for the real exports.  Its rounds are
# bounded by the small language memory in this contract (exact paths <= 16 and
# each distinct non-match pattern <= 4), and it is substantially faster in
# Python than a general sparse Hopcroft implementation on large tries.
# While refining we can reject as soon as *more* than MAX_ROWS live classes
# exist: refinement never merges classes, so the final canonical image would
# exceed the row cap as well.

def _moore_minimize(n, m, trans, accept, live_count=None):
    if n <= 1:
        return [0] * n
    block = [0 if not x else 1 for x in accept]
    num = len(set(block))
    if num <= 1:
        return block
    if live_count is None:
        live_count = n
    while True:
        mapping = {}
        new = [0] * n
        # Local bindings keep the hot loop modest.
        get = mapping.get
        for s in range(n):
            row = trans[s]
            key = (block[s],) + tuple(block[t] for t in row)
            v = get(key)
            if v is None:
                v = len(mapping)
                mapping[key] = v
            new[s] = v
        if len(mapping) == num:
            return new
        block = new
        num = len(mapping)
        # The rows eventually exported are classes that contain live states.
        # A sink class may currently also contain live states, but counting it
        # once can only under-estimate the final number of live classes.
        seen = set()
        for s in range(live_count):
            seen.add(block[s])
            if len(seen) > MAX_ROWS:
                raise PolicyError("image row cap")

# ---------------------------------------------------------------------------
# Binding parser paths to registry symbols.

def _bind(node, name_to_sym):
    kind = node.kind
    if kind in ATOM_KINDS:
        node.ps = tuple(name_to_sym[x] for x in node.path)
        return
    if kind == "not":
        _bind(node.child, name_to_sym)
    else:  # and / or
        _bind(node.left, name_to_sym)
        _bind(node.right, name_to_sym)

def _collect_match_paths(node, out):
    kind = node.kind
    if kind == "match":
        out.add(node.ps)
    elif kind in NONMATCH_KINDS:
        return
    elif kind == "not":
        _collect_match_paths(node.child, out)
    else:
        _collect_match_paths(node.left, out)
        _collect_match_paths(node.right, out)

def _eval_pred(node, p, mask):
    kind = node.kind
    if kind == "match":
        return node.ps == p
    if kind == "startswith" or kind == "endswith" or kind == "contains":
        return bool(mask & (1 << node.nmi))
    if kind == "not":
        return not _eval_pred(node.child, p, mask)
    if kind == "and":
        return _eval_pred(node.left, p, mask) and _eval_pred(node.right, p, mask)
    if kind == "or":
        return _eval_pred(node.left, p, mask) or _eval_pred(node.right, p, mask)
    raise PolicyError("predicate")

# ---------------------------------------------------------------------------

def create(text, registry, parsed=None):
    """Compile *text* over *registry* and return the canonical image.

    registry is the protocol list of {"name": ..., "label": ...}.  Raises
    PolicyError when the policy is malformed, references a nonregistered
    name, or has an image larger than the protocol's row cap.
    """
    if parsed is None:
        parsed = parse_policy(text)
    names = {s["name"] for s in registry}
    for n in parsed.referenced_names:
        if n not in names:
            raise PolicyError("unregistered service")

    # Columns are in increasing service-label order, not registry order.
    ordered = sorted(registry, key=lambda s: s["label"])
    sym_of = {s["name"]: i for i, s in enumerate(ordered)}
    m = len(ordered)

    # Per-policy distinct non-match atoms define product-component bits.
    nm_index = {}
    for i, (kind, path) in enumerate(parsed.nonmatch_atoms):
        ps = tuple(sym_of[x] for x in path)
        nm_index[(kind, ps)] = i
    k = len(parsed.nonmatch_atoms)

    # Bind every AST atom path and non-match component index.
    for pred, action in parsed.rules:
        _bind(pred, sym_of)
    for pred, action in parsed.rules:
        kind = pred.kind
        if kind in ATOM_KINDS:
            pass
        # Walk and assign nm indices.
    def assign_nm(node):
        kind = node.kind
        if kind in ATOM_KINDS:
            if kind in NONMATCH_KINDS:
                node.nmi = nm_index[(kind, node.ps)]
        elif kind == "not":
            assign_nm(node.child)
        else:
            assign_nm(node.left)
            assign_nm(node.right)
    for pred, action in parsed.rules:
        assign_nm(pred)

    # Build the non-match component automata (at most four).
    comps = [_nonmatch_component(kind, tuple(sym_of[x] for x in path), m)
             for kind, path in parsed.nonmatch_atoms]

    # Acceptance function over a scenario: either no match atom is true
    # (None), or one exact match path p is true and every other is false.
    simple_allow = set()
    simple_drop = set()
    complex_rules = []
    for pred, action in parsed.rules:
        if pred.kind == "match":
            (simple_allow if action == "allow" else simple_drop).add(pred.ps)
        else:
            match_paths = set()
            _collect_match_paths(pred, match_paths)
            none_tbl = 0
            for mask in range(1 << k):
                if _eval_pred(pred, None, mask):
                    none_tbl |= 1 << mask
            path_tbl = {}
            for p in match_paths:
                tbl = 0
                for mask in range(1 << k):
                    if _eval_pred(pred, p, mask):
                        tbl |= 1 << mask
                path_tbl[p] = tbl
            complex_rules.append((action, none_tbl, path_tbl))

    table_cache = {}
    def scenario_table(p):
        try:
            return table_cache[p]
        except KeyError:
            pass
        tbl = 0
        for mask in range(1 << k):
            allow = (p is not None and p in simple_allow)
            drop = (p is not None and p in simple_drop)
            for action, none_tbl, path_tbl in complex_rules:
                if p is None:
                    bit = (none_tbl >> mask) & 1
                else:
                    bit = (path_tbl.get(p, none_tbl) >> mask) & 1
                if bit:
                    if action == "allow":
                        allow = True
                    else:
                        drop = True
            if allow and not drop:
                tbl |= 1 << mask
        table_cache[p] = tbl
        return tbl

    # Trie of every distinct exact match path.
    all_match_paths = {tuple(sym_of[x] for x in p) for p in parsed.match_paths}
    children = [{}]
    words = [()]
    is_full = [False]
    for p in all_match_paths:
        node = 0
        for a in p:
            nxt = children[node].get(a)
            if nxt is None:
                nxt = len(children)
                children[node][a] = nxt
                children.append({})
                words.append(words[node] + (a,))
                is_full.append(False)
            node = nxt
        is_full[node] = True

    # Lazy product component state tuples.
    start_nm = (0,) * k
    nm_ids = {start_nm: 0}
    nm_tuples = [start_nm]
    nm_masks = []
    if k:
        nm_masks.append(sum((1 << i) for i, comp in enumerate(comps)
                            if comp[2][0]))
    else:
        nm_masks.append(0)
    nm_rows = [None]

    def get_nm_id(t):
        try:
            return nm_ids[t]
        except KeyError:
            nid = len(nm_tuples)
            nm_ids[t] = nid
            nm_tuples.append(t)
            mask = 0
            for i, comp in enumerate(comps):
                if comp[2][t[i]]:
                    mask |= 1 << i
            nm_masks.append(mask)
            nm_rows.append(None)
            return nid

    def nm_row(nid):
        row = nm_rows[nid]
        if row is None:
            t = nm_tuples[nid]
            if k:
                row = []
                for a in range(m):
                    nt = tuple(comps[i][1][t[i]][a] for i in range(k))
                    row.append(get_nm_id(nt))
                nm_rows[nid] = row
            else:
                row = [0] * m
                nm_rows[nid] = row
        return row

    state_ids = {(0, 0): 0}
    keys = [(0, 0)]
    trans = []
    accept = []
    pos = 0
    while pos < len(keys):
        trie_id, nid = keys[pos]
        word = words[trie_id] if trie_id >= 0 else None
        p = word if trie_id >= 0 and is_full[trie_id] else None
        accept.append(bool((scenario_table(p) >> nm_masks[nid]) & 1))
        nrow = nm_row(nid)
        row = []
        if trie_id >= 0:
            ch = children[trie_id]
            for a in range(m):
                nt = ch.get(a, -1)
                nn = nrow[a]
                key = (nt, nn)
                sid = state_ids.get(key)
                if sid is None:
                    sid = len(keys)
                    state_ids[key] = sid
                    keys.append(key)
                row.append(sid)
        else:
            for a in range(m):
                key = (-1, nrow[a])
                sid = state_ids.get(key)
                if sid is None:
                    sid = len(keys)
                    state_ids[key] = sid
                    keys.append(key)
                row.append(sid)
        trans.append(row)
        pos += 1

    n = len(trans)
    if not any(accept):
        return {"accept": [False], "rows": [[DENY] * m]}

    # Keep only states that can reach an accepting state.  The start state is
    # automatically live here because every state in this BFS graph is
    # reachable from it and at least one accepting state exists.
    rev = [[] for _ in range(n)]
    for s in range(n):
        for t in trans[s]:
            rev[t].append(s)
    live = bytearray(n)
    stack = [s for s in range(n) if accept[s]]
    for s in stack:
        live[s] = 1
    while stack:
        t = stack.pop()
        for s in rev[t]:
            if not live[s]:
                live[s] = 1
                stack.append(s)
    if not live[0]:
        return {"accept": [False], "rows": [[DENY] * m]}

    live_states = [s for s in range(n) if live[s]]
    live_map = [-1] * n
    for i, s in enumerate(live_states):
        live_map[s] = i
    ln = len(live_states)
    sink = ln
    mtrans = []
    for s in live_states:
        row = trans[s]
        mtrans.append([live_map[t] if live[t] else sink for t in row])
    mtrans.append([sink] * m)
    maccept = [accept[s] for s in live_states] + [False]

    block_of = _moore_minimize(ln + 1, m, mtrans, maccept, live_count=ln)
    sink_class = block_of[sink]
    start_class = block_of[live_map[0]]

    # Canonical breadth-first numbering of the live residual classes.
    class_order = [start_class]
    class_id = {start_class: 0}
    reps = {}
    for s in range(ln):
        cl = block_of[s]
        if cl != sink_class and cl not in reps:
            reps[cl] = s
    out_rows = []
    out_accept = []
    qi = 0
    while qi < len(class_order):
        cl = class_order[qi]
        rep = reps[cl]
        out_accept.append(bool(maccept[rep]))
        row = []
        for a in range(m):
            t = mtrans[rep][a]
            if t == sink:
                row.append(DENY)
            else:
                tc = block_of[t]
                if tc == sink_class:
                    row.append(DENY)
                else:
                    ni = class_id.get(tc)
                    if ni is None:
                        ni = len(class_order)
                        class_id[tc] = ni
                        class_order.append(tc)
                    row.append(ni)
        out_rows.append(row)
        qi += 1
        if qi > MAX_ROWS:
            raise PolicyError("image row cap")
    if len(class_order) > MAX_ROWS:
        raise PolicyError("image row cap")
    # All live classes must have been visited.
    if len(class_order) != len(reps):
        # This should be impossible: all live states are reachable from the
        # start through live states.  Treat it as a rejected policy rather
        # than emit a partial image.
        raise PolicyError("internal reachability")
    return {"accept": out_accept, "rows": out_rows}
